import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';
import { QueryClient, QueryClientProvider } from 'react-query';
import { AuthProvider, useAuth } from './contexts/AuthContext';
import Login from './components/auth/Login';
import Register from './components/auth/Register';
import Dashboard from './components/dashboard/Dashboard';
import ProtectedRoute from './components/auth/ProtectedRoute';
import './index.css';

// Create a client
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: 1,
      refetchOnWindowFocus: false,
    },
  },
});

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <AuthProvider>
        <Router>
          <div className="min-h-screen relative font-[Poppins,sans-serif] overflow-x-hidden">
            {/* Animated Blobs Background */}
            <div className="fixed inset-0 -z-10">
              <div className="absolute top-[-10%] left-[-10%] w-[60vw] h-[60vw] bg-gradient-to-br from-blue-200 via-purple-200 to-pink-200 rounded-full filter blur-3xl opacity-60 animate-blob1" />
              <div className="absolute bottom-[-15%] right-[-10%] w-[50vw] h-[50vw] bg-gradient-to-tr from-pink-100 via-blue-100 to-purple-200 rounded-full filter blur-2xl opacity-50 animate-blob2" />
            </div>
            <Routes>
              <Route path="/login" element={<Login />} />
              <Route path="/register" element={<Register />} />
              <Route path="/dashboard/*" element={
                <ProtectedRoute>
                  <Dashboard />
                </ProtectedRoute>
              } />
              <Route path="/" element={<Navigate to="/dashboard" replace />} />
            </Routes>
            <Toaster
              position="top-right"
              toastOptions={{
                duration: 4000,
                style: {
                  background: 'rgba(255,255,255,0.85)',
                  color: '#222',
                  boxShadow: '0 8px 32px 0 rgba(31,38,135,0.13)',
                  backdropFilter: 'blur(8px)',
                  border: '1px solid rgba(255,255,255,0.18)',
                  borderRadius: '1rem',
                  fontFamily: 'Poppins, Inter, Segoe UI, Roboto, Arial, sans-serif',
                  fontWeight: 500,
                },
                success: {
                  duration: 3000,
                  iconTheme: {
                    primary: '#38bdf8',
                    secondary: '#fff',
                  },
                },
                error: {
                  duration: 5000,
                  iconTheme: {
                    primary: '#f87171',
                    secondary: '#fff',
                  },
                },
              }}
            />
            <style>{`
              @keyframes blob1 { 0%,100%{transform:scale(1)translate(0,0);} 50%{transform:scale(1.1)translate(40px,-30px);} }
              @keyframes blob2 { 0%,100%{transform:scale(1)translate(0,0);} 50%{transform:scale(1.08)translate(-30px,40px);} }
              .animate-blob1 { animation: blob1 12s infinite ease-in-out; }
              .animate-blob2 { animation: blob2 14s infinite ease-in-out; }
              body, html { font-family: 'Poppins', 'Inter', 'Segoe UI', 'Roboto', 'Arial', sans-serif; }
            `}</style>
          </div>
        </Router>
      </AuthProvider>
    </QueryClientProvider>
  );
}

export default App;
